1	//! # This model works on top of the generated `feeds` SQL table
2	//!
3	//! ```sql
4	//!     CREATE TABLE "feeds" (
5	//!       "id" INTEGER PRIMARY KEY AUTOINCREMENT,
6	//!       "createdAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
7	//!       "updatedAt" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
8	//!       "reference" TEXT NOT NULL UNIQUE,
9	//!       "title" TEXT NOT NULL
10	//!     );
11	//! ```
12	
13	use askama::Template;
14	use rand::distributions::{Alphanumeric, DistString};
15	use serde::{Deserialize, Serialize};
16	use std::error::Error;
17	use tracing::debug;
18	
19	use crate::database::{DatabaseError, Pool};
20	use crate::vars::{email_domain, web_url};
21	
22	/// Form input type — only contains fields submitted by the user.
23	#[derive(Debug, Deserialize)]
24	pub struct CreateFeedForm {
25	    pub title: String,
26	}
27	
28	/// Internal domain type used to create and render a new feed.
29	/// `reference` is `None` before saving and `Some` after.
30	#[derive(Debug, Serialize, Deserialize, Clone)]
31	pub struct NewFeed {
32	    pub title: String,
33	    pub reference: Option<String>,
34	}
35	
36	/// Represents an individual feed and its related email address and title.
37	#[derive(Debug, Serialize, Deserialize)]
38	pub struct Feed {
39	    pub id: i32,
40	    pub created_at: String,
41	    pub updated_at: String,
42	    /// The `reference` of a [`Feed`] is a randomly generated alphanumeric
43	    /// string that is used as the email recipient and the unique ID of each
44	    /// [`Feed`].
45	    pub reference: String,
46	    pub title: String,
47	}
48	
49	impl Feed {
50	    /// Returns a [`Feed`]'s `title` given its `reference`.
51	    pub async fn get_title_given_reference(
52	        reference: &str,
53	        pool: &Pool,
54	    ) -> Result<String, sqlx::Error> {
55	        let (title,): (String,) =
56	            sqlx::query_as("SELECT title FROM feeds WHERE reference = $1")
57	                .bind(reference)
58	                .fetch_one(pool)
59	                .await?;
60	
61	        Ok(title)
62	    }
63	
64	    /// Returns whether a feed with the given `reference` exists. Used at
65	    /// SMTP RCPT-TO time to reject mail for unknown feeds before accepting
66	    /// the message body.
67	    pub async fn exists(
68	        reference: &str,
69	        pool: &Pool,
70	    ) -> Result<bool, sqlx::Error> {
71	        let (exists,): (bool,) = sqlx::query_as(
72	            "SELECT EXISTS(SELECT 1 FROM feeds WHERE reference = $1)",
73	        )
74	        .bind(reference)
75	        .fetch_one(pool)
76	        .await?;
77	
78	        Ok(exists)
79	    }
80	}
81	
82	#[derive(Template, Clone)]
83	#[template(path = "sentinel_entry.html", ext = "html")]
84	pub struct SentinelTemplate {
85	    pub email_domain: String,
86	    pub reference: String,
87	    pub title: String,
88	    pub web_url: String,
89	}
90	
91	#[derive(Template, Clone)]
92	#[template(path = "created.html", ext = "html")]
93	#[allow(dead_code)]
94	pub struct FeedCreatedTemplate {
95	    pub email_domain: String,
96	    pub reference: String,
97	    pub title: String,
98	    pub web_url: String,
99	    pub entry: SentinelTemplate,
100	}
101	
102	impl NewFeed {
103	    fn new_reference() -> String {
104	        Alphanumeric
105	            .sample_string(&mut rand::thread_rng(), 16)
106	            .to_lowercase()
107	    }
108	
109	    /// References are a random 16-char alphanumeric string (36^16 possible
110	    /// values), so collisions are vanishingly rare but not impossible. One
111	    /// retry with a freshly generated reference is enough to close the gap.
112	    const MAX_SAVE_ATTEMPTS: u32 = 2;
113	
114	    pub async fn save(
115	        &mut self,
116	        pool: &Pool,
117	    ) -> Result<String, Box<dyn Error>> {
118	        let mut attempt = 0;
119	
120	        loop {
121	            attempt += 1;
122	            let reference = self
123	                .reference
124	                .get_or_insert_with(NewFeed::new_reference)
125	                .to_owned();
126	
127	            let content = SentinelTemplate {
128	                email_domain: email_domain(),
